import math

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def compute_max_gcd(a):
    max_gcd = 0
    for b in range(1, a):
        xor_ab = a ^ b
        and_ab = a & b
        current_gcd = gcd(xor_ab, and_ab)
        max_gcd = max(max_gcd, current_gcd)
    return max_gcd

def main():
    q = int(input())
    results = []
    for _ in range(q):
        a = int(input())
        results.append(compute_max_gcd(a))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
